#!/usr/bin/env python3
from collections import Counter
import sys

def analyze_emoji_file(filename):
    with open(filename, 'r', encoding='utf-8') as f:
        content = f.read()

    # Count unique emojis
    emoji_count = Counter(content)
    print("Unique emoji count:")
    for emoji, count in emoji_count.most_common():
        print(f"{emoji}: {count} times (Unicode: U+{ord(emoji):04X})")

    # Look for repeating patterns
    print("\nAnalyzing repeating patterns...")
    patterns = []
    for length in range(2, 10):
        for i in range(len(content) - length):
            pattern = content[i:i+length]
            if content.count(pattern) > 1:
                patterns.append((pattern, content.count(pattern)))

    # Sort by frequency and show top 10
    patterns = sorted(set(patterns), key=lambda x: x[1], reverse=True)[:10]
    print("\nTop repeating patterns:")
    for pattern, count in patterns:
        print(f"Pattern: {pattern} appears {count} times")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python3 analyze_emoji.py <emoji_file>")
        sys.exit(1)
    analyze_emoji_file(sys.argv[1])

#!/usr/bin/env python3
import base64

def emoji_to_binary(emoji):
    # Convert emojis to binary pattern
    positive_emojis = ['👍', '🌝', '⚽️', '📈', '🔔', '❤️‍🩹']
    negative_emojis = ['👎', '🌚', '💩', '📉', '🔕', '💔']

    if emoji in positive_emojis:
        return '1'
    elif emoji in negative_emojis:
        return '0'
    return ''

def main():
    with open('/home/ctfplayer/ctf_files/emoji.txt', 'r') as f:
        emoji_text = f.read()

    # Convert to binary
    binary = ''
    for char in emoji_text:
        if char not in ['➕', '➖']:
            bit = emoji_to_binary(char)
            binary += bit

    print("=== Binary Pattern ===")
    print(binary[:50] + "...")  # Show first 50 bits

    # Try different groupings
    print("\n=== 8-bit Grouping ===")
    chars = []
    for i in range(0, len(binary) - 7, 8):
        byte = binary[i:i+8]
        if len(byte) == 8:
            try:
                chars.append(chr(int(byte, 2)))
            except:
                pass

    ascii_text = ''.join(chars)
    print(f"ASCII: {ascii_text[:50]}")

    # Try base64 decoding
    print("\n=== Base64 Attempts ===")
    try:
        # Pad binary to multiple of 6 bits
        padded_binary = binary + '0' * ((6 - len(binary) % 6) % 6)
        b64_chars = []

        # Convert 6 bits at a time to base64 char
        b64_alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        for i in range(0, len(padded_binary) - 5, 6):
            chunk = padded_binary[i:i+6]
            if len(chunk) == 6:
                index = int(chunk, 2)
                if index < 64:
                    b64_chars.append(b64_alphabet[index])

        b64_str = ''.join(b64_chars)
        # Try different paddings
        for padding in ['', '=', '==']:
            try:
                decoded = base64.b64decode(b64_str + padding).decode()
                print(f"Decoded (padding={padding}): {decoded[:50]}")
            except:
                continue

    except Exception as e:
        print(f"Base64 decoding failed: {e}")

    # Look for potential flag format
    print("\n=== Flag Pattern Search ===")
    if 'csawctf{' in ascii_text:
        start = ascii_text.index('csawctf{')
        end = ascii_text.find('}', start)
        if end != -1:
            flag = ascii_text[start:end+1]
            print(f"Found potential flag: {flag}")

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
from collections import Counter

def analyze_emoji_patterns():
    with open('/home/ctfplayer/ctf_files/emoji.txt', 'r') as f:
        content = f.read()

    # Split emojis and operations
    operations = []
    current_group = []
    binary_pattern = []

    # Map common emojis to analyze patterns
    emoji_mapping = {
        '👍': '1',  # positive/thumbs up
        '👎': '0',  # negative/thumbs down
        '🌝': '1',  # full/bright
        '🌚': '0',  # new/dark
        '📈': '1',  # upward trend
        '📉': '0',  # downward trend
        '🔔': '1',  # bell on
        '🔕': '0',  # bell off
        '❤️‍🩹': '1',  # heart
        '💔': '0',  # broken heart
        '➕': '+',  # plus
        '➖': '-',  # minus
    }

    # First pass: Convert to binary pattern
    binary_str = ''
    segments = []
    current_segment = []

    for char in content:
        if char in ['➕', '➖']:
            if current_segment:
                segments.append(''.join(current_segment))
                current_segment = []
            segments.append(char)
        else:
            current_segment.append(char)

    if current_segment:
        segments.append(''.join(current_segment))

    print("=== Segment Analysis ===")
    for i, segment in enumerate(segments[:10]):
        print(f"Segment {i}: {segment}")

        # Convert to binary where possible
        binary_segment = ''
        for emoji in segment:
            if emoji in emoji_mapping:
                binary_segment += emoji_mapping[emoji]

        if binary_segment:
            print(f"Binary: {binary_segment}")

            # Try to convert binary to ASCII
            if len(binary_segment) >= 8:
                try:
                    ascii_chars = []
                    for i in range(0, len(binary_segment), 8):
                        byte = binary_segment[i:i+8]
                        if len(byte) == 8:
                            ascii_chars.append(chr(int(byte, 2)))
                    ascii_str = ''.join(ascii_chars)
                    print(f"ASCII: {ascii_str}")
                except:
                    pass

    # Look for repeating patterns
    print("\n=== Pattern Analysis ===")
    pattern_lengths = []
    for i in range(2, len(segments)):
        if segments[i] == segments[i-2]:
            pattern_lengths.append(i)

    if pattern_lengths:
        print(f"Found repeating patterns of lengths: {pattern_lengths}")

    # Try mathematical operations
    print("\n=== Mathematical Operations ===")
    result = []
    operator = '+'
    for segment in segments:
        if segment in ['➕', '➖']:
            operator = segment
        else:
            # Convert segment to binary
            binary_val = ''
            for emoji in segment:
                if emoji in emoji_mapping:
                    binary_val += emoji_mapping[emoji]

            if binary_val:
                try:
                    val = int(binary_val, 2)
                    if operator == '+':
                        result.append(val)
                    else:
                        result.append(-val)
                except:
                    pass

    if result:
        print(f"Mathematical sequence: {result[:10]}...")
        # Try converting result numbers to ASCII
        try:
            ascii_result = ''.join(chr(abs(x) % 128) for x in result)
            print(f"ASCII result: {ascii_result[:50]}")

            # Look for flag pattern
            if 'csawctf{' in ascii_result:
                start = ascii_result.index('csawctf{')
                end = ascii_result.find('}', start)
                if end != -1:
                    flag = ascii_result[start:end+1]
                    print(f"\nPotential flag found: {flag}")
        except:
            pass

if __name__ == '__main__':
    analyze_emoji_patterns()
